python - <<'EOF'
p='minidb/parser.py'
s=open(p).read()
i=s.index('def parse(tokens')
head=s[:i]
body='''class _Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return Token(TokenType.EOF, "")

    def next(self) -> Token:
        tok = self.peek()
        if tok.type is not TokenType.EOF:
            self.pos += 1
        return tok

    def fail(self, msg: str) -> SQLSyntaxError:
        tok = self.peek()
        shown = tok.value if tok.type is not TokenType.EOF else "end of input"
        return SQLSyntaxError(f"{msg} near {shown!r}")

    def is_kw(self, word: str) -> bool:
        tok = self.peek()
        return tok.type is TokenType.KEYWORD and tok.value == word

    def is_op(self, sym: str) -> bool:
        tok = self.peek()
        return tok.type is TokenType.OPERATOR and tok.value == sym

    def expect_kw(self, word: str) -> None:
        if not self.is_kw(word):
            raise self.fail(f"expected {word}")
        self.next()

    def expect_op(self, sym: str) -> None:
        if not self.is_op(sym):
            raise self.fail(f"expected {sym!r}")
        self.next()

    def ident(self) -> str:
        if self.peek().type is not TokenType.IDENTIFIER:
            raise self.fail("expected identifier")
        return self.next().value

    def at_eof(self) -> bool:
        return self.peek().type is TokenType.EOF

    # statements
    def statement(self) -> Statement:
        tok = self.peek()
        if tok.type is TokenType.KEYWORD:
            if tok.value == "CREATE":
                return self.create()
            if tok.value == "DROP":
                self.next()
                self.expect_kw("TABLE")
                return DropTableStmt(self.ident())
            if tok.value == "INSERT":
                return self.insert()
            if tok.value == "SELECT":
                return self.select()
            if tok.value == "DELETE":
                self.next()
                self.expect_kw("FROM")
                table = self.ident()
                return DeleteStmt(table, self.opt_where())
        raise self.fail("expected statement")

    def opt_where(self):
        if self.is_kw("WHERE"):
            self.next()
            return self.expr()
        return None

    def create(self) -> Statement:
        self.next()
        self.expect_kw("TABLE")
        table = self.ident()
        self.expect_op("(")
        cols = []
        while True:
            name = self.ident()
            tok = self.peek()
            if tok.type is TokenType.KEYWORD and tok.value in ("INTEGER", "TEXT", "BOOLEAN"):
                self.next()
                cols.append(ColumnDef(name, ColumnType(tok.value)))
            else:
                raise self.fail("expected column type")
            if self.is_op(","):
                self.next()
                continue
            break
        self.expect_op(")")
        return CreateTableStmt(table, tuple(cols))

    def literal_value(self) -> Value:
        tok = self.peek()
        if tok.type is TokenType.INTEGER:
            self.next()
            return int(tok.value)
        if tok.type is TokenType.STRING:
            self.next()
            return tok.value
        if tok.type is TokenType.KEYWORD and tok.value in ("TRUE", "FALSE", "NULL"):
            self.next()
            return {"TRUE": True, "FALSE": False, "NULL": None}[tok.value]
        raise self.fail("expected literal")

    def insert(self) -> Statement:
        self.next()
        self.expect_kw("INTO")
        table = self.ident()
        cols = None
        if self.is_op("("):
            self.next()
            names = [self.ident()]
            while self.is_op(","):
                self.next()
                names.append(self.ident())
            self.expect_op(")")
            cols = tuple(names)
        self.expect_kw("VALUES")
        self.expect_op("(")
        vals = [self.literal_value()]
        while self.is_op(","):
            self.next()
            vals.append(self.literal_value())
        self.expect_op(")")
        return InsertStmt(table, cols, tuple(vals))

    def select(self) -> Statement:
        self.next()
        cols = None
        if self.is_op("*"):
            self.next()
        else:
            names = [self.ident()]
            while self.is_op(","):
                self.next()
                names.append(self.ident())
            cols = tuple(names)
        self.expect_kw("FROM")
        table = self.ident()
        return SelectStmt(table, cols, self.opt_where())

    # expressions
    def expr(self) -> Expr:
        left = self.and_expr()
        while self.is_kw("OR"):
            self.next()
            left = Or(left, self.and_expr())
        return left

    def and_expr(self) -> Expr:
        left = self.not_expr()
        while self.is_kw("AND"):
            self.next()
            left = And(left, self.not_expr())
        return left

    def not_expr(self) -> Expr:
        if self.is_kw("NOT"):
            self.next()
            return Not(self.not_expr())
        return self.predicate()

    def predicate(self) -> Expr:
        left = self.primary()
        tok = self.peek()
        if tok.type is TokenType.OPERATOR and tok.value in COMPARISON_OPS:
            self.next()
            return Comparison(tok.value, left, self.primary())
        if self.is_kw("IS"):
            self.next()
            negated = False
            if self.is_kw("NOT"):
                self.next()
                negated = True
            self.expect_kw("NULL")
            return IsNull(left, negated)
        return left

    def primary(self) -> Expr:
        tok = self.peek()
        if tok.type is TokenType.IDENTIFIER:
            self.next()
            return ColumnRef(tok.value)
        if self.is_op("("):
            self.next()
            inner = self.expr()
            self.expect_op(")")
            return inner
        return Literal(self.literal_value())


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    p = _Parser(tokens)
    stmt = p.statement()
    if p.is_op(";"):
        p.next()
    if not p.at_eof():
        raise p.fail("unexpected token")
    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    p = _Parser(tokens)
    out: list[Statement] = []
    while True:
        while p.is_op(";"):
            p.next()
        if p.at_eof():
            return out
        out.append(p.statement())
        if not p.is_op(";") and not p.at_eof():
            raise p.fail("unexpected token")


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    p = _Parser(tokens)
    expr = p.expr()
    if not p.at_eof():
        raise p.fail("unexpected token")
    return expr
'''
